/* NFC – Nazari Fulfilment Center: gedeelde stijl voor alle subpagina's */
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:#F7F7F5;color:#111827;font:16px/1.6 system-ui,-apple-system,"Segoe UI",Roboto,Inter,Arial,sans-serif}
h1,h2,h3{line-height:1.15;letter-spacing:-.01em;color:inherit}
h1{font-size:46px;margin:0 0 18px}
h2{font-size:32px;margin:0 0 14px}
h3{font-size:20px;margin:0 0 8px}
p{margin:0 0 14px}
a{color:#C2410C}a:hover{color:#9A3412}
img,svg{max-width:100%}
.wrap{max-width:1160px;margin:0 auto;padding:0 24px}
.smal{max-width:820px}
.kop{background:#0E1A2B;color:#fff}
.kop .wrap{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:14px;padding-top:16px;padding-bottom:16px}
.logo{display:flex;align-items:center;gap:10px;color:#fff;text-decoration:none}
.logo b{display:block;font-size:22px;letter-spacing:.02em;line-height:1}
.logo small{display:block;font-size:11px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:#FDBA74;margin-top:3px}
.logo:hover{color:#fff}
.menu{display:flex;flex-wrap:wrap;align-items:center;gap:18px;font-size:15px}
.menu a{color:#E2E8F0;text-decoration:none}
.menu a:hover,.menu a[aria-current]{color:#fff;text-decoration:underline;text-underline-offset:4px}
.menu .rand{border:1px solid #475569;border-radius:10px;padding:9px 14px;color:#fff;font-weight:600}
.knop{display:inline-block;background:#C2410C;color:#fff!important;text-decoration:none!important;font-weight:600;padding:12px 18px;border-radius:10px}
.knop:hover{background:#9A3412}
.knop.licht{background:transparent;border:1px solid #475569}
.held{background:#0E1A2B;color:#fff;padding:44px 0 64px}
.held p.lead{font-size:19px;color:#CBD5E1;max-width:720px}
.held .knoppen{display:flex;flex-wrap:wrap;gap:12px;margin-top:22px}
.label{display:inline-block;background:#1E2D44;color:#FDBA74;font-weight:600;font-size:14px;padding:6px 12px;border-radius:999px;margin-bottom:14px}
.kruimel{font-size:14px;color:#94A3B8;margin-bottom:18px}
.kruimel a{color:#CBD5E1}
.blok{padding:56px 0}
.blok.donker{background:#0E1A2B;color:#fff}
.blok.donker p{color:#CBD5E1}
.raster{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,245px),1fr));gap:18px}
.kaart{background:#fff;border:1px solid #E5E7EB;border-radius:16px;padding:24px}
.blok.donker .kaart{background:#13233A;border-color:#1E3352}
.kaart p{color:#4B5563;margin:0}
.blok.donker .kaart p{color:#CBD5E1}
.vink{list-style:none;padding:0;margin:0 0 14px}
.vink li{position:relative;padding-left:28px;margin:8px 0}
.vink li:before{content:"";position:absolute;left:4px;top:6px;width:12px;height:7px;border-left:2.5px solid #C2410C;border-bottom:2.5px solid #C2410C;transform:rotate(-45deg)}
.tabel{width:100%;border-collapse:collapse;background:#fff;border:1px solid #E5E7EB;border-radius:14px;overflow:hidden;font-size:15px}
.tabel th,.tabel td{text-align:left;padding:12px 16px;border-bottom:1px solid #E5E7EB;vertical-align:top}
.tabel th{background:#F1F5F9;font-weight:600}
.tabel td.r,.tabel th.r{text-align:right;white-space:nowrap}
.tabel tr:last-child td{border-bottom:0}
.scroll{overflow-x:auto}
.stappen{counter-reset:s;list-style:none;padding:0;margin:0;display:grid;gap:14px;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr))}
.stappen li{counter-increment:s;background:#fff;border:1px solid #E5E7EB;border-radius:16px;padding:22px 22px 22px 70px;position:relative}
.stappen li:before{content:counter(s);position:absolute;left:22px;top:20px;width:34px;height:34px;border-radius:999px;background:#C2410C;color:#fff;font-weight:700;display:flex;align-items:center;justify-content:center}
.stappen b{display:block;margin-bottom:4px}
details{background:#fff;border:1px solid #E5E7EB;border-radius:14px;padding:16px 20px;margin-bottom:10px}
summary{cursor:pointer;font-weight:600;font-size:17px}
details p{margin:10px 0 0;color:#4B5563}
.cta{background:#C2410C;color:#fff;border-radius:20px;padding:34px;display:flex;flex-wrap:wrap;gap:18px;align-items:center;justify-content:space-between}
.cta h2{margin:0 0 6px;font-size:28px}
.cta p{margin:0;color:#FFEDD5}
.cta .knop{background:#fff;color:#9A3412!important}
.cta .knop:hover{background:#FFEDD5}
.artikel{background:#fff;border:1px solid #E5E7EB;border-radius:18px;padding:34px}
.artikel h2{font-size:26px;margin-top:30px}
.artikel h3{margin-top:22px}
.artikel p,.artikel li{color:#1F2937}
.meta{color:#64748B;font-size:14px;margin-bottom:22px}
.let{background:#FFF7ED;border:1px solid #FED7AA;border-radius:14px;padding:16px 20px;margin:18px 0}
.voet{background:#0E1A2B;color:#CBD5E1;padding:44px 0 30px;font-size:14px;margin-top:56px}
.voet .wrap{display:grid;gap:26px;grid-template-columns:repeat(auto-fit,minmax(min(100%,200px),1fr))}
.voet b{color:#fff;display:block;margin-bottom:8px;font-size:15px}
.voet a{color:#CBD5E1;text-decoration:none;display:block;margin:5px 0}
.voet a:hover{color:#fff;text-decoration:underline}
.voet .klein{grid-column:1/-1;border-top:1px solid #1E3352;padding-top:18px;color:#94A3B8}
@media (max-width:760px){
  h1{font-size:34px}h2{font-size:26px}
  .menu{gap:12px;font-size:14px}
  .menu .verberg{display:none}
  .artikel{padding:22px}
  .held{padding:30px 0 44px}
}

.tabel tr.groep td{background:#F8FAFC;font-weight:700;font-size:13px;text-transform:uppercase;letter-spacing:.04em;color:#4B5563;padding:10px 16px}
.kaart h2.kop3{font-size:20px;line-height:1.15;letter-spacing:-.01em;margin:0 0 8px}
.voorwaarden ol{padding-left:22px}.voorwaarden li{margin:0 0 8px}@media print{header,footer,nav,.kruimel{display:none!important}}
